var DEFAULT_CONTRACT_DESIGN = { primary: "#13384b", accent: "#f58a00", text: "#333333", paper: "#ffffff", company: "DIGITAL NORTE", tagline: "Tango Gest\xE3o de Cr\xE9ditos", contacts: "", address: "", style: "ribbon" };
function contractDesign(c) {
  const design = { ...DEFAULT_CONTRACT_DESIGN, ...c.design };
  if (!c.design?.style && c.design?.primary === "#262626" && c.design?.accent === "#666666") return { ...design, primary: DEFAULT_CONTRACT_DESIGN.primary, accent: DEFAULT_CONTRACT_DESIGN.accent };
  return design;
}
function newSoftwareContract() {
  return { id: crypto.randomUUID(), number: "", title: "Contrato de Licenciamento e Venda de Software", client: "", nif: "", software: "Tango Gest\xE3o de Cr\xE9ditos", updatedAt: (/* @__PURE__ */ new Date()).toISOString(), sections: modelo_contrato_software_default.sections.map((section) => ({ ...section })) };
}
function contractText(text, contract) {
  const fields = { software: contract.software, cliente: contract.client || "[DENOMINA\xC7\xC3O DO CLIENTE]", nif: contract.nif || "[NIF DO CLIENTE]", numero: contract.number || "[N\xDAMERO DO CONTRATO]" };
  return text.replace(/\{\{(software|cliente|nif|numero)\}\}/g, (_, key) => fields[key]);
}
function validateSoftwareContract(value) {
  const c = value;
  if (c?.design?.style !== void 0 && c.design.style !== "ribbon") return false;
  if (c?.design?.logo !== void 0 && (typeof c.design.logo !== "string" || c.design.logo !== "" && !/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(c.design.logo))) return false;
  if (c?.design !== void 0 && (!c.design || !["primary", "accent", "text", "paper"].every((k) => /^#[0-9a-f]{6}$/i.test(c.design[k])) || !["company", "tagline", "contacts", "address"].every((k) => typeof c.design[k] === "string"))) return false;
  return !!c && ["id", "number", "title", "client", "nif", "software", "updatedAt"].every((key) => typeof c[key] === "string") && Array.isArray(c.sections) && c.sections.length > 0 && c.sections.length <= 100 && c.sections.every((s) => typeof s.id === "string" && typeof s.title === "string" && typeof s.body === "string") && new Set(c.sections.map((s) => s.id)).size === c.sections.length;
}
export {
  DEFAULT_CONTRACT_DESIGN,
  contractDesign,
  contractText,
  newSoftwareContract,
  validateSoftwareContract
};
